// THE INTEROPERABILITY GATE: fixtures in tests/fixtures/ were
// generated by the PYTHON implementation (scripts/make_fixtures.py).
// These tests fail unless this client opens the same Vault v3 file,
// decrypts the same entries, imports the same MKBAK package, and
// writes files the Python cross-check (scripts/crosscheck_python.py)
// can open in return.

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import {
  BackupRefusedError,
  exportPackage,
  importPackageWithPairing,
  importPackageWithRecovery,
  inspectPackage,
} from "../src/vault/backup.js";
import {
  DeviceIdentity,
  PairingTargetIdentity,
  verifyDeviceCard,
} from "../src/vault/device.js";
import { verifyPairingPayload, type PairingRecord } from "../src/vault/pairings.js";
import { b64decode, b64encode, randomBytes } from "../src/vault/encoding.js";
import { rotationStatus } from "../src/vault/rotation.js";
import {
  VaultCorruptError,
  VaultSession,
  WrongPasswordError,
  generatePassword,
} from "../src/vault/vault.js";
import { b64urlDecode, b64urlEncode, getAssertion } from "../src/vault/passkey.js";

const here = dirname(fileURLToPath(import.meta.url));
const FIX = join(here, "fixtures");
const OUT = join(FIX, "out");

const vaultBytes = new Uint8Array(readFileSync(join(FIX, "fixture.mykey")));
const pkgBytes = new Uint8Array(readFileSync(join(FIX, "fixture.mykeybak")));
const legacyPkgBytes = new Uint8Array(readFileSync(join(FIX, "fixture-v1.mykeybak")));
const nopairPkgBytes = new Uint8Array(readFileSync(join(FIX, "fixture-nopair.mykeybak")));
const expected = JSON.parse(readFileSync(join(FIX, "expected.json"), "utf8"));

function entryView(e: {
  service: string; username: string; password: string; url: string;
  notes: string; totp_secret: string; tags: string[]; favourite: boolean;
  android_app?: unknown;
}) {
  return {
    service: e.service, username: e.username, password: e.password,
    url: e.url, notes: e.notes, totp_secret: e.totp_secret,
    tags: e.tags, favourite: e.favourite,
    android_app: e.android_app ?? null,
  };
}

function expectedViews() {
  return expected.entries.map((e: any) => entryView(e)).sort(
    (a: any, b: any) => a.service.localeCompare(b.service),
  );
}

describe("Python-fixture vault opens in the TS client", () => {
  it("unlocks with the master password and decrypts the same entries", async () => {
    const s = await VaultSession.openWithPassword(vaultBytes, expected.password);
    expect(s.vaultId).toBe(expected.vault_id);
    const views = s.listEntries().map(entryView).sort((a, b) => a.service.localeCompare(b.service));
    expect(views).toEqual(expectedViews());
    expect(s.hasRecovery()).toBe(true);
    expect(s.auditSealed).toBe(false);
  });

  it("rejects a wrong password", async () => {
    await expect(
      VaultSession.openWithPassword(vaultBytes, "not-the-password-123"),
    ).rejects.toBeInstanceOf(WrongPasswordError);
  });

  it("unlocks with the recovery phrase", async () => {
    const s = await VaultSession.openWithPhrase(vaultBytes, expected.phrase);
    expect(s.listEntries()).toHaveLength(4);
  });

  it("rejects a valid-but-wrong recovery phrase", async () => {
    await expect(
      VaultSession.openWithPhrase(
        vaultBytes,
        "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about",
      ),
    ).rejects.toBeInstanceOf(WrongPasswordError);
  });

  it("refuses a tampered entry ciphertext (core hash seal)", async () => {
    const tampered = JSON.parse(Buffer.from(vaultBytes).toString("utf8"));
    const ct = tampered.entries[0].secret.ciphertext;
    tampered.entries[0].secret.ciphertext = (ct[0] === "A" ? "B" : "A") + ct.slice(1);
    await expect(
      VaultSession.openWithPassword(
        new Uint8Array(Buffer.from(JSON.stringify(tampered))),
        expected.password,
      ),
    ).rejects.toBeInstanceOf(VaultCorruptError);
  });

  it("sees the desktop-enrolled agent and rebuilds its bundle on save", async () => {
    const s = await VaultSession.openWithPassword(vaultBytes, expected.password);
    const saved = await s.serialize();
    const file = JSON.parse(Buffer.from(saved).toString("utf8"));
    expect(Object.keys(file.bundles)).toContain(expected.agent.id);
    expect(file.slots.map((x: any) => x.id)).toContain("master");
    const again = await VaultSession.openWithPassword(saved, expected.password);
    expect(again.listEntries()).toHaveLength(4);
    // The Android-app binding survives a TS serialize → reopen
    // round trip (package + signing-cert hash + label).
    const shop = again.listEntries().find((e) => e.service === "shopapp");
    expect(shop?.android_app).toEqual({
      package: "com.example.shop",
      cert_sha256: "0123456789abcdef".repeat(4),
      label: "Shop App",
    });
  });
});

describe("password rotation fields in the Python fixture", () => {
  it("reads the exact set dates, overrides and vault default Python wrote", async () => {
    const s = await VaultSession.openWithPassword(vaultBytes, expected.password);
    const rot = expected.rotation;
    expect(s.vaultSettings().default_rotate_days).toBe(rot.default_rotate_days);
    for (const entry of s.listEntries()) {
      const want = rot.entries[entry.service];
      expect(entry.password_set_at).toBe(rot.password_set_at);
      expect(entry.rotate_days).toBe(want.rotate_days);
      const status = rotationStatus(entry, rot.default_rotate_days, rot.status_now);
      expect(status.state).toBe(want.state);
    }
  });
});

describe("MKBAK recovery import (Python-generated package)", () => {
  it("inspects the package and verifies its signature", () => {
    const info = inspectPackage(pkgBytes);
    expect(info.vaultId).toBe(expected.vault_id);
    expect(info.version).toBe(2);
    expect(info.legacy).toBe(false);
    expect(info.recoveryTwoFactor).toBe(true);
    expect(info.sourceFingerprint).toBe(expected.backup.source_fingerprint);
    expect(info.fingerprintMatchesHeader).toBe(true);
    expect(info.signatureValid).toBe(true);
    expect(info.recipients.map((r) => r.type)).toContain("recovery");
    expect(info.recipients.map((r) => r.type)).toContain("pairing");
  });

  it("imports with phrase + backup code (two-factor) and opens the vault", async () => {
    const result = await importPackageWithRecovery(
      pkgBytes,
      expected.phrase,
      expected.backup.source_fingerprint,
      expected.backup.backup_code,
    );
    expect(result.vaultId).toBe(expected.vault_id);
    expect(result.via).toBe("recovery");
    expect(result.packageVersion).toBe(2);
    expect(result.legacy).toBe(false);
    const s = await VaultSession.openWithPassword(result.vaultBytes, expected.password);
    const views = s.listEntries().map(entryView).sort((a, b) => a.service.localeCompare(b.service));
    expect(views).toEqual(expectedViews());
  });

  it("refuses phrase-only on a v2 package (two-factor rule)", async () => {
    await expect(
      importPackageWithRecovery(pkgBytes, expected.phrase, expected.backup.source_fingerprint),
    ).rejects.toThrow(/two-factor/);
  });

  it("refuses a wrong backup code, fails closed", async () => {
    const wrong = "abandon abandon abandon abandon abandon abandon abandon abandon";
    await expect(
      importPackageWithRecovery(
        pkgBytes, expected.phrase, expected.backup.source_fingerprint, wrong,
      ),
    ).rejects.toBeInstanceOf(BackupRefusedError);
  });

  it("refuses a malformed backup code plainly", async () => {
    await expect(
      importPackageWithRecovery(
        pkgBytes, expected.phrase, expected.backup.source_fingerprint, "not a real code",
      ),
    ).rejects.toThrow(/backup code/);
  });

  it("accepts the code typed with odd case and spacing", async () => {
    const shouted = "  " + expected.backup.backup_code.toUpperCase().split(" ").join("   ") + " ";
    const result = await importPackageWithRecovery(
      pkgBytes, expected.phrase, expected.backup.source_fingerprint, shouted,
    );
    expect(result.vaultId).toBe(expected.vault_id);
  });

  it("imports the legacy v1 package with the phrase alone, labelled legacy", async () => {
    const info = inspectPackage(legacyPkgBytes);
    expect(info.version).toBe(1);
    expect(info.legacy).toBe(true);
    expect(info.recoveryTwoFactor).toBe(false);
    const result = await importPackageWithRecovery(
      legacyPkgBytes,
      expected.phrase,
      expected.backup.source_fingerprint,
    );
    expect(result.legacy).toBe(true);
    const s = await VaultSession.openWithPassword(result.vaultBytes, expected.password);
    expect(s.listEntries()).toHaveLength(4);
  });

  it("imports via the pairing key on the pre-revocation package", async () => {
    const priv = b64decode(expected.pairing.priv_b64);
    const result = await importPackageWithPairing(
      pkgBytes, priv, expected.backup.source_fingerprint,
    );
    expect(result.via).toBe(`pairing:${expected.pairing.target_id}`);
    const s = await VaultSession.openWithPassword(result.vaultBytes, expected.password);
    expect(s.listEntries()).toHaveLength(4);
  });

  it("the post-revocation package has NO pairing slot", async () => {
    const info = inspectPackage(nopairPkgBytes);
    expect(info.recipients.map((r) => r.type)).not.toContain("pairing");
    const priv = b64decode(expected.pairing.priv_b64);
    await expect(
      importPackageWithPairing(nopairPkgBytes, priv, expected.backup.source_fingerprint),
    ).rejects.toBeInstanceOf(BackupRefusedError);
  });

  it("refuses when the independent fingerprint does not match", async () => {
    await expect(
      importPackageWithRecovery(
        pkgBytes,
        expected.phrase,
        "0000:0000:0000:0000:0000:0000:0000:0000",
        expected.backup.backup_code,
      ),
    ).rejects.toBeInstanceOf(BackupRefusedError);
  });

  it("refuses a tampered package (signature)", async () => {
    const tampered = JSON.parse(Buffer.from(pkgBytes).toString("utf8"));
    tampered.created_at = tampered.created_at + 1;
    await expect(
      importPackageWithRecovery(
        new Uint8Array(Buffer.from(JSON.stringify(tampered))),
        expected.phrase,
        expected.backup.source_fingerprint,
        expected.backup.backup_code,
      ),
    ).rejects.toBeInstanceOf(BackupRefusedError);
  });
});

describe("TS-exported MKBAK v2 package (for the Python cross-check)", () => {
  it("exports a v2 package Python must open three ways; refuses the failures", async () => {
    mkdirSync(OUT, { recursive: true });
    const s = await VaultSession.openWithPassword(vaultBytes, expected.password);

    // This client becomes an enrolled device of the fixture vault.
    const identity = DeviceIdentity.generate("ts-fixture-device");
    const record = verifyDeviceCard(identity.card() as unknown as Record<string, unknown>);
    s.putDeviceRecord({ ...record, enrolled_at: 1700000000, revoked_at: null });

    // A pairing target with the export scope is enrolled too.
    const target = PairingTargetIdentity.generate("export", "ts-fixture-target");
    const base = verifyPairingPayload(target.payload() as unknown as Record<string, unknown>);
    const pairingRecord: PairingRecord = {
      ...base,
      scopes: ["export", "pull", "push"],
      enrolled_at: 1700000000,
      expires_at: null,
      enabled: true,
      revoked_at: null,
    };
    s.putPairingRecord(pairingRecord as unknown as Record<string, any>);
    // The vault carrying both registries, for the Python side to read.
    writeFileSync(join(OUT, "paired.mykey"), await s.serialize());

    const backupRecoveryPub = s.backupRecoveryPub();
    expect(backupRecoveryPub).not.toBeNull();
    const out = await exportPackage({
      vaultBytes: await s.serialize(),
      vaultId: s.vaultId,
      source: identity,
      devices: s.devicesRegistry(),
      pairings: s.pairingsRegistry() as Record<string, PairingRecord>,
      backupRecoveryPub: backupRecoveryPub!,
    });
    expect(out.recipientLabels).toContain(`device:${identity.deviceId}`);
    expect(out.recipientLabels).toContain(`paired:${target.targetId}`);
    expect(out.recipientLabels).toContain("recovery");
    expect(out.backupCode.split(" ")).toHaveLength(8);
    // The backup code must NOT appear anywhere in the package bytes.
    const pkgText = Buffer.from(out.packageBytes).toString("utf8");
    expect(pkgText.includes(out.backupCode)).toBe(false);
    expect(pkgText.includes(out.backupCode.split(" ").slice(0, 4).join(" "))).toBe(false);

    writeFileSync(join(OUT, "ts-export.mykeybak"), out.packageBytes);
    writeFileSync(join(OUT, "ts-device-keys.json"), identity.serialize());
    writeFileSync(
      join(OUT, "ts-export.json"),
      JSON.stringify(
        {
          backup_code: out.backupCode,
          source_fingerprint: identity.fingerprint,
          pairing_target_id: target.targetId,
          pairing_fingerprint: target.fingerprint,
          pairing_priv_b64: b64encode(target.xPrivateRaw),
          vault_id: s.vaultId,
        },
        null,
        2,
      ),
    );

    // TS-side round trips against the TS-made package.
    const viaRecovery = await importPackageWithRecovery(
      out.packageBytes, expected.phrase, identity.fingerprint, out.backupCode,
    );
    expect(viaRecovery.via).toBe("recovery");
    await expect(
      importPackageWithRecovery(out.packageBytes, expected.phrase, identity.fingerprint),
    ).rejects.toThrow(/two-factor/);
    const viaPairing = await importPackageWithPairing(
      out.packageBytes, target.xPrivateRaw, identity.fingerprint,
    );
    expect(viaPairing.via).toBe(`pairing:${target.targetId}`);
    const opened = await VaultSession.openWithPassword(viaRecovery.vaultBytes, expected.password);
    expect(opened.listEntries()).toHaveLength(4);
    // The pairing registry survived the round trip in the core.
    expect(Object.keys(opened.pairingsRegistry())).toContain(target.targetId);
  });

  it("an unenrolled device cannot export (mirrors the desktop)", async () => {
    const s = await VaultSession.openWithPassword(vaultBytes, expected.password);
    const stranger = DeviceIdentity.generate("stranger");
    await expect(
      exportPackage({
        vaultBytes: await s.serialize(),
        vaultId: s.vaultId,
        source: stranger,
        devices: s.devicesRegistry(),
        pairings: s.pairingsRegistry() as Record<string, PairingRecord>,
        backupRecoveryPub: s.backupRecoveryPub()!,
      }),
    ).rejects.toBeInstanceOf(BackupRefusedError);
  });
});

describe("TS-written files for the Python cross-check", () => {
  it("writes a resaved copy and a modified copy of the fixture vault", async () => {
    mkdirSync(OUT, { recursive: true });
    const s = await VaultSession.openWithPassword(vaultBytes, expected.password);
    writeFileSync(join(OUT, "resaved.mykey"), await s.serialize());
    const entry = s.listEntries().find((e) => e.service === "github")!;
    await s.updateEntry(entry.id, { password: "ts-changed-password-1" });
    await s.addEntry({
      service: "tsadded",
      username: "ts-user",
      password: "ts-added-password-1",
      url: "https://ts.example",
      notes: "added by the TS client",
      totp_secret: "",
      tags: ["ts"],
      favourite: false,
    });
    writeFileSync(join(OUT, "modified.mykey"), await s.serialize());
  });

  it("creates a brand-new vault + recovery and writes it for Python", async () => {
    mkdirSync(OUT, { recursive: true });
    const password = "Ts-Created-Password-2026";
    const s = await VaultSession.createNew(password);
    const phrase = await s.setupRecovery();
    await s.addEntry({
      service: "created-service",
      username: "created-user",
      password: "created-password-1",
      url: "https://created.example",
      notes: "created by the TS client",
      totp_secret: "GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ",
      tags: ["created"],
      favourite: true,
    });
    writeFileSync(join(OUT, "created.mykey"), await s.serialize());
    writeFileSync(
      join(OUT, "created-expected.json"),
      JSON.stringify({ password, recovery_phrase: phrase, vault_id: s.vaultId }, null, 2),
    );
    const reopened = await VaultSession.openWithPhrase(await s.serialize(), phrase);
    expect(reopened.listEntries()).toHaveLength(1);
  });

  it("device wrapped slot round-trips (Android biometric design)", async () => {
    const s = await VaultSession.openWithPassword(vaultBytes, expected.password);
    const wrapKey = randomBytes(32);
    await s.addWrappedSlot("pwa-device", wrapKey);
    const saved = await s.serialize();
    const via = await VaultSession.openWithWrapKey(saved, "pwa-device", wrapKey);
    expect(via.listEntries()).toHaveLength(4);
    await expect(
      VaultSession.openWithWrapKey(saved, "pwa-device", randomBytes(32)),
    ).rejects.toBeInstanceOf(WrongPasswordError);
  });
});

describe("Passkey fixture (Python-created) opens and signs in the TS client", () => {
  const pkBytes = new Uint8Array(readFileSync(join(FIX, "fixture-passkey.mykey")));

  it("record matches the Python-written expected values", async () => {
    const s = await VaultSession.openWithPassword(pkBytes, expected.password);
    const keys = s.listPasskeys();
    expect(keys).toHaveLength(1);
    const rec = keys[0]!.passkey!;
    expect(rec.rp_id).toBe(expected.passkey.rp_id);
    expect(rec.user_name).toBe(expected.passkey.user_name);
    expect(rec.credential_id).toBe(expected.passkey.credential_id);
    expect(rec.public_key).toBe(expected.passkey.public_key);
    expect(rec.sign_count).toBe(expected.passkey.sign_count);
    // the login beside it is intact
    expect(s.listEntries()).toHaveLength(2);
  });

  it("produces an assertion (sign_count 7 → 8) and writes it for the Python cross-check", async () => {
    mkdirSync(OUT, { recursive: true });
    const s = await VaultSession.openWithPassword(pkBytes, expected.password);
    const challenge = b64urlEncode(new Uint8Array(32).fill(9));
    const a = await getAssertion(s, {
      origin: "https://example.com",
      optionsJson: { challenge, rpId: "example.com", userVerification: "required" },
      userVerified: true,
    });
    expect(s.listPasskeys()[0]!.passkey!.sign_count).toBe(8);
    const std = (b64url: string) => Buffer.from(b64urlDecode(b64url)).toString("base64");
    writeFileSync(
      join(OUT, "passkey-assertion.json"),
      JSON.stringify({
        authenticator_data: std(a.response.authenticatorData),
        client_data_json: std(a.response.clientDataJSON),
        signature: std(a.response.signature),
        credential_id: s.listPasskeys()[0]!.passkey!.credential_id,
      }, null, 2),
    );
    writeFileSync(join(OUT, "passkey-resaved.mykey"), await s.serialize());
    const again = await VaultSession.openWithPassword(await s.serialize(), expected.password);
    expect(again.listPasskeys()[0]!.passkey!.sign_count).toBe(8);
  });
});

describe("Client-native behaviour", () => {
  it("short master passwords are refused at create time", async () => {
    await expect(VaultSession.createNew("short")).rejects.toThrow(/at least 12/);
  });

  it("generator honours the 16-character floor", () => {
    expect(() => generatePassword(12)).toThrow(/at least 16/);
    expect(generatePassword(20)).toHaveLength(20);
  });

  it("CRUD round trip with search", async () => {
    const s = await VaultSession.createNew("Crud-Test-Password-1");
    const a = await s.addEntry({
      service: "alpha", username: "u1", password: "p1", url: "",
      notes: "", totp_secret: "", tags: ["x"], favourite: false,
    });
    await expect(s.addEntry({
      service: "alpha", username: "u1", password: "p2", url: "",
      notes: "", totp_secret: "", tags: [], favourite: false,
    })).rejects.toThrow(/already exists/);
    expect(s.searchEntries("ALP")).toHaveLength(1);
    await s.updateEntry(a.id, { password: "p2" });
    expect(s.getEntry(a.id).password).toBe("p2");
    await s.deleteEntry(a.id);
    expect(s.listEntries()).toHaveLength(0);
  });
});
